SELECT s.interval_code, s.sentiment_available, s.fundamental_available, COUNT(*) AS n, SUM(p.realized_pnl > 0) AS wins, ROUND(SUM(p.realized_pnl), 4) AS pnl, ROUND(SUM(p.entry_price * p.quantity), 2) AS notional, ROUND(AVG(s.total_score), 1) AS avg_score FROM crypto_ai.paper_position p JOIN crypto_ai.trade_signal s ON s.id = p.signal_id WHERE p.status IN ('CLOSED','STOPPED') GROUP BY s.interval_code, s.sentiment_available, s.fundamental_available ORDER BY s.interval_code LIMIT 20;
SELECT DATE_FORMAT(generated_at, '%Y-%m-%d %H:00') AS hr_utc, COUNT(*) AS n, SUM(sentiment_available) AS n_avail FROM crypto_ai.trade_signal WHERE symbol = 'BTCUSDT' AND interval_code = '1m' AND generated_at BETWEEN '2026-10-11 00:00:00' AND '2026-10-15 06:00:00' GROUP BY hr_utc ORDER BY hr_utc LIMIT 110;
SELECT (m.id IS NULL) AS no_managed, (m.entry_quality_score IS NULL) AS eq_null, COUNT(*) AS n, ROUND(SUM(p.realized_pnl), 4) AS pnl FROM crypto_ai.paper_position p LEFT JOIN crypto_ai.wallet_managed_position m ON m.entry_signal_id = p.signal_id WHERE p.status IN ('CLOSED','STOPPED') GROUP BY no_managed, eq_null LIMIT 10;